+                        continue
+                    }
+                    let nx = x + dx
+                    let ny = y + dy
+                    if nx >= 0 && nx < width && ny >= 0 && ny < height {
+                        let nidx = ny * width + nx
+                        if grid[nidx] == 1 {
+                            neighbors = neighbors + 1
+                        }
+                    }
+                }
+            }
+            if grid[idx] == 1 {
+                if neighbors == 2 || neighbors == 3 {
+                    out[idx] = 1
+                }
+            } else {
+                if neighbors == 3 {
+                    out[idx] = 1
+                }
+            }
+        }
+    }
